import styled from '@emotion/styled';
import { theme } from 'theme';

import type { Position3 } from '../../../../types';

interface PositionProps {
  $position?: Position3;
}

const positionTextStyles: Record<Position3, { fontSize: string }> = {
  '1': { fontSize: '40px' },
  '2': { fontSize: '24px' },
  '3': { fontSize: '24px' },
};

const positionItemStyles: Record<
  Position3,
  {
    width: string;
    borderRadius: string;
    order: string;
    padding: string;
    background: string;
  }
> = {
  '1': {
    width: 'calc(43.44% - 10.67px)',
    borderRadius: '8px',
    order: '2',
    padding: '1px',
    background:
      'linear-gradient(317.35deg, #FFEA00 -12.35%, #D3A238 105.27%)',
  },
  '2': {
    width: 'calc(28.28% - 10.67px)',
    borderRadius: '8px',
    order: '1',
    padding: '1px',
    background: 'rgba(20, 20, 20, 0.12)',
  },
  '3': {
    width: 'calc(28.28% - 10.67px)',
    order: '3',
    borderRadius: '8px',
    padding: '1px',
    background: 'rgba(20, 20, 20, 0.12)',
  },
};

const positionContainerStyles: Record<Position3, { borderRadius: string; paddingBottom: string }> =
  {
    '1': { borderRadius: '8px', paddingBottom: '52.59%' },
    '2': { borderRadius: '8px', paddingBottom: '58.07%' },
    '3': { borderRadius: '8px', paddingBottom: '45.89%' },
  };

export const StyledFlagsBox = styled.div({
  width: '100%',
  display: 'flex',
  paddingTop: '48px',
  flexWrap: 'wrap',
  gap: '16px',
  alignItems: 'flex-end',
  justifyContent: 'space-between',
});

export const StyledFlaItem = styled.div<PositionProps>(({ $position }) => ({
  position: 'relative',
  ...($position != null ? positionItemStyles[$position] : {}),
}));

export const StyledFlagItemContainer = styled.div<PositionProps>(
  ({ $position }) => ({
    position: 'relative',
    overflow: 'hidden',
    ...($position != null ? positionContainerStyles[$position] : {}),
  }),
);

export const StyledFlagText = styled.div<PositionProps>(({ $position }) => ({
  color: '#fff',
  fontFamily: theme.fonts.heading,
  ...($position != null ? positionTextStyles[$position] : {}),
}));

export const StyledImage = styled.img({
  width: '100%',
  height: '100%',
  objectFit: 'cover',
  position: 'absolute',
});

export const StyledBoxContent = styled.div({
  width: '100%',
  height: '100%',
  padding: '32px 24px',
  display: 'flex',
  alignItems: 'flex-end',
  justifyContent: 'center',
  objectFit: 'cover',
  position: 'absolute',
  background:
    'linear-gradient(0deg, rgba(23, 23, 23, 0.24), rgba(23, 23, 23, 0.24)), linear-gradient(180deg, rgba(0, 0, 0, 0) -7.96%, #000000 129.96%)',
});
